import {writeFile,readFile,stat} from 'node:fs/promises';import {pathToFileURL} from 'node:url';import {createHash} from 'node:crypto';import path from 'node:path';
const runtime=process.argv[2],source=process.argv[3],output=process.argv[4],report=process.argv[5],load=x=>import(pathToFileURL(path.join(runtime,x+'.js')).href);
const {analyzeRepository}=await load('analysis/analyze'),{SemanticStore}=await load('semantic/store'),{scanRepository}=await load('repository/repository'),{canonical,digest}=await load('semantic/model');
const scan=await scanRepository(source,output);const inventory=digest(canonical([...scan.snapshot.fileContents].map(([f,t])=>[f,digest(t)]).sort()));
const stages=[];const original=SemanticStore.prototype.publish;SemanticStore.prototype.publish=function(...args){this.hooks.measure=(stage,ms)=>stages.push({stage,ms});return original.apply(this,args)};
const start=performance.now(),result=await analyzeRepository(source,{output}),elapsedMs=performance.now()-start,analysisResources=process.resourceUsage();
if(result.manifest.semanticCore?.status==='failed')throw Error(result.manifest.semanticCore.reason);
const end=await scanRepository(source,output);if(digest(canonical([...end.snapshot.fileContents].map(([f,t])=>[f,digest(t)]).sort()))!==inventory)throw Error('Source changed during measured analysis');
const store=new SemanticStore(path.join(output,'semantic.sqlite'));const checksums={};
function rows(name,sql){const h=createHash('sha256');let count=0;for(const row of store.sql(sql).iterate()){h.update(canonical(row)+'\n');count++}checksums[name]={count,sha256:h.digest('hex')}}
rows('visibleClaims',"SELECT c.key FROM sc_active a JOIN sc_claims c ON c.id=a.claim WHERE a.snapshot=1 ORDER BY c.key");
rows('occurrences',"SELECT e.key,o.context,o.start_byte,o.end_byte,o.line,o.column_num,o.end_line,o.end_column,o.role FROM sc_occurrences o JOIN sc_entities e ON e.id=o.entity ORDER BY e.key");
rows('calls',"SELECT x.key caller,y.key callee,c.site_count,c.confidence,e.key sample FROM sc_calls c JOIN sc_entities x ON x.id=c.caller JOIN sc_entities y ON y.id=c.callee JOIN sc_claims e ON e.id=c.sample_claim WHERE snapshot=1 ORDER BY x.key,y.key");
rows('scopeRows','SELECT * FROM cq_scope_nodes ORDER BY scope,node');rows('boundaries','SELECT * FROM cq_boundaries ORDER BY framework,node');
rows('edges','SELECT * FROM edges ORDER BY id');rows('diagnostics','SELECT code,severity,message,file,line,column,adapter,metadata_json FROM diagnostics ORDER BY code,severity,message,file,line,column,adapter,metadata_json');
rows('nodes',"SELECT * FROM nodes WHERE kind<>'repository' ORDER BY id");
const reportData={elapsedMs,analysisResources,stages,inventory,selectedFiles:scan.snapshot.files.length,codeFiles:[...scan.snapshot.fileContents].filter(([f])=>/\.(?:[cm]?tsx?|jsx?|rs|py|java|c|h|cpp|cc|cxx|go|cs)$/.test(f)).map(([file,text])=>({file,lines:text.split('\n').length})),manifest:result.manifest,checksums,integrity:store.db.pragma('integrity_check',{simple:true}),foreignKeys:store.db.pragma('foreign_key_check'),durability:{journal:store.db.pragma('journal_mode',{simple:true}),synchronous:store.db.pragma('synchronous',{simple:true})},databaseBytes:(await stat(path.join(output,'semantic.sqlite'))).size};store.close();await writeFile(report,JSON.stringify(reportData,null,2)+'\n');console.log(JSON.stringify({report,elapsedMs,maxRssKiB:analysisResources.maxRSS,checksums}));

